def details_block():
    shots=[('deslanado',t('La herramienta importa','A ferramenta importa'),t('Un gesto de cepillado en un manto de pelo corto.','Un xesto de cepillado nun manto de pelo curto.')),('bruce-bano-1',t('Manos con oficio','Mans con oficio'),t('Las manos de Shadia durante el baño de Bruce.','As mans de Shadia durante o baño de Bruce.')),('orejeras',t('Los pequeños cuidados','Os pequenos coidados'),t('Preparación del secado con protección para el ruido.','Preparación do secado con protección para o ruído.'))]
    return '<section class="section craft-journal" id="el-oficio"><div class="wrap"><div class="journal-heading"><div><span class="eyebrow">'+t('De cerca, Pelucans','De preto, Pelucans')+'</span><h2>'+t('El cariño está<br>en los detalles.','O agarimo está<br>nos detalles.')+'</h2></div><p>'+t('Manos, herramientas y pequeños gestos del día a día. Fotografías reales del salón, para ver también lo que hay detrás del acabado.','Mans, ferramentas e pequenos xestos do día a día. Fotografías reais do salón, para ver tamén o que hai detrás do acabado.')+'</p></div><div class="craft-frames">'+''.join(f'<figure><div><img src="assets/img/real/{photo}.webp" alt="{copy}" loading="lazy"></div><figcaption><span>0{i+1}</span><h3>{title}</h3><p>{copy}</p></figcaption></figure>' for i,(photo,title,copy) in enumerate(shots))+'</div></div></section>'

def enhance(body,file):
    if file=='consejos.html':
        block=seasonal_block()
        pos=body.find('<section',body.find('</header>')+9)
        body=body[:pos]+block+body[pos:]
    if file in ('index.html','servicios.html'):
        pos=body.rfind('<section')
        body=body[:pos]+details_block()+body[pos:]
    if file=='index.html':
        pos=body.rfind('<section')
        body=body[:pos]+'<section class="section journal-discover"><div class="wrap"><span class="eyebrow">'+t('El cuaderno de Pelucans','O caderno de Pelucans')+'</span><h2>'+t('Aprender a cuidarlo.<br>También es quererlo.','Aprender a coidalo.<br>Tamén é querelo.')+'</h2><div class="journal-links"><a href="consejos.html#calendario">'+t('Su calendario de cuidados','O seu calendario de coidados')+' ↗</a><a href="consejo-secador-sin-miedo.html">'+t('Si le preocupa el secador','Se lle preocupa o secador')+' ↗</a><a href="consejo-mitos-del-manto.html">'+t('Seis mitos, bien explicados','Seis mitos, ben explicados')+' ↗</a></div></div></section>'+body[pos:]
    if file=='servicio-bano-manto.html':
        pos=body.rfind('<section')
        body=body[:pos]+'<aside class="wrap dryer-link"><span class="eyebrow">'+t('Un cuidado a su ritmo','Un coidado ao seu ritmo')+'</span><h2>'+t('¿El secador le preocupa?','Preocúpalle o secador?')+'</h2><p>'+t('Cuéntanoslo antes de venir. Hemos preparado una guía para acompañar esa sensibilidad con calma.','Cóntanolo antes de vir. Preparamos unha guía para acompañar esa sensibilidade con calma.')+'</p><a class="link-arrow" href="consejo-secador-sin-miedo.html">'+t('Leer la guía','Ler a guía')+' ↗</a></aside>'+body[pos:]
    return body
